#include "KS/SRC/ks/FEPanel_shared.h"

static inline matrix4x4 operator*(const matrix4x4 &a, const matrix4x4 &b)
{
    matrix4x4 local;
    asm(
        "lqc2 vf1,0x0(%2)\n"
        "lqc2 vf2,0x10(%2)\n"
        "lqc2 vf3,0x20(%2)\n"
        "lqc2 vf4,0x30(%2)\n"
        "lqc2 vf5,0x0(%1)\n"
        "lqc2 vf6,0x10(%1)\n"
        "lqc2 vf7,0x20(%1)\n"
        "lqc2 vf8,0x30(%1)\n"
        "vmulax.xyzw ACC,vf1,vf5\n"
        "vmadday.xyzw ACC,vf2,vf5\n"
        "vmaddaz.xyzw ACC,vf3,vf5\n"
        "vmaddw.xyzw vf9,vf4,vf5\n"
        "vmulax.xyzw ACC,vf1,vf6\n"
        "vmadday.xyzw ACC,vf2,vf6\n"
        "vmaddaz.xyzw ACC,vf3,vf6\n"
        "vmaddw.xyzw vf10,vf4,vf6\n"
        "vmulax.xyzw ACC,vf1,vf7\n"
        "vmadday.xyzw ACC,vf2,vf7\n"
        "vmaddaz.xyzw ACC,vf3,vf7\n"
        "vmaddw.xyzw vf11,vf4,vf7\n"
        "vmulax.xyzw ACC,vf1,vf8\n"
        "vmadday.xyzw ACC,vf2,vf8\n"
        "vmaddaz.xyzw ACC,vf3,vf8\n"
        "vmaddw.xyzw vf12,vf4,vf8\n"
        "sqc2 vf9,0x0(%0)\n"
        "sqc2 vf10,0x10(%0)\n"
        "sqc2 vf11,0x20(%0)\n"
        "sqc2 vf12,0x30(%0)\n"
        :
        : "r" (&local), "r" (&a), "r" (&b));
    return local;
}

struct nglQuad {
    char data[0x100];
};

extern void nglInitQuad(nglQuad *);
extern void nglSetQuadRect(nglQuad *, float, float, float, float);
extern void nglSetQuadColor(nglQuad *, unsigned int);
extern void nglSetQuadZ(nglQuad *, float);

class PanelText : public PanelGeom {
public:
    stringx fontname;
    color32 color;
    unsigned char justification;
    float linespacing;
    uint32 numtextlines;
    stringx text;
    nglQuad quad;

    virtual void Init(PanelQuad **pquads);
    virtual void Init(PanelQuad **pquads, matrix4x4 matrix);
    virtual void Draw(float alpha = 1);
};

void PanelText::Init(PanelQuad** pquads, matrix4x4 parent_matrix)
{
	matrix4x4 this_matrix = parent_matrix*matrix;

	// text needs to be drawn here, with the appropriate matrix
	// right now, an incorrect quad will be drawn
	nglInitQuad(&quad);
	vector3d bbc = boundboxcenter;
	vector3d bbs = boundboxsize;
	nglSetQuadRect(&quad, bbc.x - bbs.x, bbc.y - bbs.y, bbc.x + bbs.x, bbc.y + bbs.y);
	nglSetQuadColor(&quad, ((unsigned int)(0) << 24) | ((unsigned int)(0x64) << 16) | ((unsigned int)(0x64) << 8) | (unsigned int)(0));
	nglSetQuadZ(&quad, 1.0f);
//	if(next) next->Init(pquads, parent_matrix);
	if(children) children->Init(pquads, this_matrix);
}
